const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).map(Number);
    if (input.length < 4) return;
    let [a, b, c, l] = input;

    // Sort sides so that a <= b <= c
    [a, b, c] = [a, b, c].sort((x, y) => x - y);

    // Total number of ways to distribute at most l centimeters among 3 sticks
    // This is C(l + 3, 3) = (l+3)(l+2)(l+1)/6
    const totalWays = (l + 1) * (l + 2) * (l + 3) / 6;

    let badWays = 0;

    // We need to count ways where triangle inequality fails: a' + b' <= c'
    // a' = a + da, b' = b + db, c' = c + dc
    // da + db + dc <= l, da, db, dc >= 0
    // (a + da) + (b + db) <= (c + dc)  => da + db - dc <= c - a - b
    // Let D = c - a - b

    const D = c - a - b;

    // Iterate over total increment used t = da + db + dc from 0 to l
    // For a fixed t, we need da + db - dc <= D
    // Since dc = t - da - db, condition becomes:
    // da + db - (t - da - db) <= D => 2(da + db) <= t + D
    // Let S = da + db. We need S <= floor((t + D) / 2)
    // Also S >= 0 and dc = t - S >= 0 => S <= t
    // Number of (da, db) pairs for a given S is S + 1
    // Number of (da, db, dc) for fixed t is sum_{S=0}^{S_max} (S + 1)
    // where S_max = min(t, floor((t + D) / 2))

    // We can iterate over dc (increase of largest stick) or t.
    // Iterating t is fine, O(l) which is 3e5.

    for (let t = 0; t <= l; t++) {
        // Max sum of increases for smaller sticks S = da + db
        // Condition: 2S <= t + D  => S <= floor((t + D) / 2)
        const maxS = Math.floor((t + D) / 2);
        const S_limit = Math.min(t, maxS);

        if (S_limit >= 0) {
            // Sum of (S + 1) for S = 0 to S_limit
            // = (S_limit + 1)(S_limit + 2) / 2
            badWays += (S_limit + 1) * (S_limit + 2) / 2;
        }
    }

    const result = totalWays - badWays;
    console.log(result);
}

solve();
